import base64,io,json,os,pathlib,subprocess,tarfile,datetime
root=pathlib.Path('/home/zbs/rf-round7-final-review-20261019')
root.mkdir(exist_ok=False)
raw=base64.b64decode('')
with tarfile.open(fileobj=io.BytesIO(raw),mode='r:gz') as tf:
 for m in tf.getmembers():
  if not (root/m.name).resolve().is_relative_to(root) or not m.isfile():raise RuntimeError('Unsafe archive member')
 tf.extractall(root,filter='data')
env=os.environ.copy();env.update(CUDA_VISIBLE_DEVICES='',OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',KUBECONFIG=str(root/'nonexistent-offline-kubeconfig'))
cmd=['/home/zbs/rf-ablation-20261019-1425/lab/.venv/bin/python','-m','pytest','tests/test_round7.py','tests/test_round7_reassessment.py','tests/test_round7_final_review.py','-q','--junitxml='+str(root/'pytest-linux.xml')]
start=datetime.datetime.now(datetime.timezone.utc).isoformat()
with (root/'pytest-linux.log').open('w') as f:p=subprocess.run(cmd,cwd=root,env=env,stdout=f,stderr=subprocess.STDOUT)
record=dict(started_utc=start,finished_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),host=os.uname().nodename,root=str(root),command=cmd,exit_code=p.returncode,cluster_resources_changed=False,real_gpu_workloads=False)
(root/'execution.json').write_text(json.dumps(record,indent=2))
print(json.dumps(record));print((root/'pytest-linux.log').read_text());print('JUNIT_JSON '+json.dumps((root/'pytest-linux.xml').read_text()))
raise SystemExit(p.returncode)
